const METAUX_ID = 'recagFquBCz04FJfi';
const ENV_ID = 'recA9nSrxiyq1Ta9x';

// Cause reelle des doublons constatee le 19/09 (1106 lignes au lieu de 12) :
// le noeud precedent ne renvoyait PAS le champ Date (deux parametres fields[]
// identiques s'ecrasent dans le noeud HTTP n8n) et seulement 100 lignes. Le
// noeud ne filtre donc plus les champs et trie par date decroissante.
function siteIdOf(s) {
  if (typeof s === 'string') return s;
  if (s && typeof s === 'object' && s.id) return s.id;
  return String(s);
}

const calendarEvents = $('Lit le calendrier').first().json.value || [];
const existingRecords = $json.records || [];

const existingKeys = new Set();
for (const r of existingRecords) {
  const rawDate = (r.fields && r.fields['fldEudIIzKQYXdh1b']) || '';
  const d = rawDate.slice(0, 10);
  const sites = (r.fields && r.fields['fldkSCBcG0xkGoIkD']) || [];
  for (const s of sites) existingKeys.add(d + '|' + siteIdOf(s));
}

const newRecords = [];
const seen = new Set();

for (const ev of calendarEvents) {
  const subject = ev.subject || '';
  const upper = subject.toUpperCase();

  // Seuls les evenements "journee sur site" comptent ici (ex. "Journee PENA") --
  // un rendez-vous ponctuel qui mentionne juste PENA dans son titre ne doit pas
  // creer un jour de planning (voir echange avec Christel du 11/09).
  const isJourneeSite = upper.includes('JOURNEE') || upper.includes('JOURN\u00c9E');
  if (!isJourneeSite) continue;

  let siteId = null;
  if (/\bPE\b/.test(upper)) siteId = ENV_ID;
  else if (/\bPM\b/.test(upper) || /\bPL\b/.test(upper) || /\bPENA\b/.test(upper)) siteId = METAUX_ID;
  if (!siteId) continue;

  const date = ((ev.start && ev.start.dateTime) || '').slice(0, 10);
  if (!date) continue;

  const key = date + '|' + siteId;
  if (seen.has(key) || existingKeys.has(key)) continue;
  seen.add(key);

  newRecords.push({
    fields: {
      fldYJwPLx9iyTfjLR: subject,
      fldEudIIzKQYXdh1b: date,
      fldkSCBcG0xkGoIkD: [siteId],
    },
  });
}

if (newRecords.length === 0) return [];

// Garde-fou : jamais plus de 20 creations d'un coup. Au-dela, c'est un bug de
// deduplication (pas 20 nouveaux jours de presence reels) -- on echoue bruyamment
// plutot que de repeupler la table.
if (newRecords.length > 20) throw new Error('Trop de nouveaux jours (' + newRecords.length + ') : deduplication probablement cassee, arret.');

return [{ json: { records: newRecords } }];

const METAUX_ID = 'recagFquBCz04FJfi';
const ENV_ID = 'recA9nSrxiyq1Ta9x';

// Pendant de "Calcule les nouveaux jours" : un jour de visite deplace ou supprime
// dans Outlook doit disparaitre de PLANNING_VISITES (sinon l'ancienne date restait
// affichee indefiniment, constate le 28/09 avec le 25/09 deplace au 23/09).
// Memes regles de lecture du titre que le noeud de creation -- les garder alignees.
function siteIdOf(s) {
  if (typeof s === 'string') return s;
  if (s && typeof s === 'object' && s.id) return s.id;
  return String(s);
}

const calendar = $('Lit le calendrier').first().json;
// Garde-fou : si le calendrier n'a pas ete lu en entier (pagination Graph) ou pas
// lu du tout, on ne supprime rien -- un jour absent serait peut-etre juste non lu.
if (!Array.isArray(calendar.value) || calendar['@odata.nextLink']) return [];

const calendarKeys = new Set();
for (const ev of calendar.value) {
  const upper = (ev.subject || '').toUpperCase();
  if (!(upper.includes('JOURNEE') || upper.includes('JOURNÉE'))) continue;
  let siteId = null;
  if (/\bPE\b/.test(upper)) siteId = ENV_ID;
  else if (/\bPM\b/.test(upper) || /\bPL\b/.test(upper) || /\bPENA\b/.test(upper)) siteId = METAUX_ID;
  if (!siteId) continue;
  const date = ((ev.start && ev.start.dateTime) || '').slice(0, 10);
  if (date) calendarKeys.add(date + '|' + siteId);
}

// Garde-fou : aucune journee sur site lue sur 2 mois = plus probablement une
// reponse Graph vide ou anormale qu'un planning reellement vide. On ne supprime
// rien ; si c'est voulu, les lignes se retirent a la main dans Airtable.
if (calendarKeys.size === 0) return [];

// Fenetre controlee : strictement apres aujourd'hui (le calendrier est lu a partir
// de maintenant, donc la journee du jour peut deja manquer) et avant la fin de la
// periode lue (2 mois). L'historique passe n'est jamais touche.
const today = $now.setZone('Europe/Paris').toISODate();
const end = $now.setZone('Europe/Paris').plus({ months: 2 }).toISODate();

const toDelete = [];
for (const r of $('Liste les jours existants').first().json.records || []) {
  const d = ((r.fields && r.fields['fldEudIIzKQYXdh1b']) || '').slice(0, 10);
  if (!d || d <= today || d >= end) continue;
  const sites = (r.fields && r.fields['fldkSCBcG0xkGoIkD']) || [];
  if (sites.length === 0) continue;
  const toujoursPrevu = sites.some((s) => calendarKeys.has(d + '|' + siteIdOf(s)));
  if (!toujoursPrevu) toDelete.push(r.id);
}

if (toDelete.length === 0) return [];

// Garde-fou : Airtable supprime au plus 10 lignes par appel, et plus de 10 jours
// retires d'un coup ressemble davantage a une lecture de calendrier ratee qu'a un
// vrai changement de planning -- on echoue bruyamment plutot que de vider la table.
if (toDelete.length > 10) throw new Error('Trop de jours a supprimer (' + toDelete.length + ') : lecture du calendrier probablement incomplete, arret.');

return [{ json: { query: toDelete.map((id) => 'records[]=' + id).join('&') } }];
